34	// defaultLimit mirrors the row-path measure_analyzer.go default. Matched so
35	// vec and row produce identical paging for requests that don't set Limit.
36	const defaultLimit uint32 = 100
37	
38	// Analyze translates a measurev1.QueryRequest + its Measure schema into a
39	// VecPlan tree. It is the vec counterpart of pkg/query/logical/measure
40	// (deprecated) but produces vec plan nodes — there is no leaf
41	// substitution into a row plan.
42	//
43	// The returned tree is structural: it carries the static (proto-derived)
44	// query parameters in `Scan.Params` and the BatchSchema for downstream
45	// nodes to consult. Runtime fields that depend on the executor's
46	// MeasureExecutionContext — the resolved `index.Query` and the entity
47	// table — are NOT populated here; the executor (G8c) fills them in
48	// before invoking Build.
49	//
50	// Errors are returned for:
51	//   - nil schema
52	//   - tag/field projection naming columns not in the schema
53	//   - GroupBy referencing a tag absent from the schema
54	//   - Agg referencing a field or tag absent from the schema, naming both or
55	//     neither of field_name/tag_name, or naming a tag whose type or family
56	//     qualification the target function does not support (design §6)
57	//
58	// GroupBy and Agg may travel together (group + aggregate), or either
59	// alone: Agg without GroupBy is a scalar reduce (single output row);
60	// GroupBy without Agg is a raw GroupBy (first-seen row per group). Both
61	// mirror the row path (measure_plan_aggregation.go / measure_plan_groupby.go).
62	//
63	// mode selects the BatchAggregation strategy when an agg operator is built:
64	// AggModeAll for single-node final reduce, AggModeMap for the distributed
65	// Map phase (G9f.2) that emits typed-column partials. AggModeReduce is
66	// rejected (the reduce plan is built liaison-side in G9f.3).
67	func Analyze(req *measurev1.QueryRequest, measureSchema *databasev1.Measure, mode measure.AggMode) (VecPlan, error) {
68		if req == nil {
69			return nil, fmt.Errorf("plan.Analyze: nil request")
70		}
71		if measureSchema == nil {
72			return nil, fmt.Errorf("plan.Analyze: nil Measure schema")
73		}
74		if pushdownErr := validateCountDistinctPushdown(req, measureSchema); pushdownErr != nil {
75			return nil, pushdownErr
76		}
77	
78		tagProjection := buildTagProjection(req)
79		fieldProjection := req.GetFieldProjection().GetNames()
80	
81		// GroupBy + Agg must be resolved BEFORE BuildBatchSchema so the Scan
82		// node's BatchSchema declares native typed columns for the GroupBy
83		// keys and Agg field. The operator (BatchAggregation.fold) hard-casts
84		// those columns to TypedColumn[int64] / [float64]; passthrough
85		// columns would panic. Storage's queryResult.batchSchema is rebuilt
86		// from the same opts in banyand/measure/query.go, so both halves of
87		// the bridge agree on column types.
88		hasGroupBy := req.GetGroupBy() != nil
89		hasAgg := req.GetAgg() != nil
90		var gbModel *model.MeasureGroupBy
91		var aggModel *model.MeasureAgg
92		if hasGroupBy {
93			var gbErr error
94			gbModel, gbErr = translateGroupBy(req, measureSchema)
95			if gbErr != nil {
96				return nil, gbErr
97			}
98		}
99		if hasAgg {
100			var aggErr error
101			aggModel, aggErr = translateAgg(req, measureSchema)
102			if aggErr != nil {
103				return nil, aggErr
104			}
105		}
106	
107		// Projection auto-coverage: BatchAggregation / BatchGroupBy locate
108		// their key and value columns by name inside the BatchSchema, which
109		// BuildBatchSchema derives from TagProjection + FieldProjection.
110		// Extend the projection implicitly so the GroupBy keys and the Agg
111		// field always materialize a column, instead of falling through to
112		// the row path when the request omitted them from its projection.
113		tagProjection = ensureGroupByProjected(tagProjection, gbModel)
114		tagProjection = ensureAggTagProjected(tagProjection, aggModel)
115		fieldProjection = ensureAggFieldProjected(fieldProjection, aggModel)
116	
117		opts := model.MeasureQueryOptions{
118			TagProjection:   tagProjection,
119			FieldProjection: fieldProjection,
120			GroupBy:         gbModel,
121			Agg:             aggModel,
122		}
123		batchSchema, schemaErr := measure.BuildBatchSchema(measureSchema, opts)
124		if schemaErr != nil {
125			return nil, fmt.Errorf("plan.Analyze: %w", schemaErr)
126		}
127	
128		var tr *timestamp.TimeRange
129		if t := req.GetTimeRange(); t != nil {
130			r := timestamp.NewInclusiveTimeRange(t.GetBegin().AsTime(), t.GetEnd().AsTime())
131			tr = &r
132		}
133	
134		var plan VecPlan = NewScan(batchSchema, ScanParams{
135			Measure:         measureSchema,
136			TimeRange:       tr,
137			TagProjection:   tagProjection,
138			FieldProjection: fieldProjection,
139			GroupBy:         gbModel,
140			Agg:             aggModel,
141		})
142	
143		if hasGroupBy || hasAgg {
144			// One BatchAggregation / BatchGroupBy node covers all three
145			// shapes (group+agg, scalar reduce, raw groupby); BuildOperators
146			// routes on which of gbModel/aggModel is set.
147			gba, gbaErr := NewGroupByAgg(plan, gbModel, aggModel, mode)
148			if gbaErr != nil {
149				return nil, gbaErr
150			}
151			plan = gba
152		}
153	
154		if t := req.GetTop(); t != nil {
155			// Match the row path (pkg/query/logical/measure.unresolvedTop):
156			// FieldValueSort==SORT_ASC keeps the lowest N (BatchTop asc=true);
157			// anything else (SORT_DESC / SORT_UNSPECIFIED) keeps the highest N.
158			asc := t.GetFieldValueSort() == modelv1.Sort_SORT_ASC
159			plan = NewTop(plan, t.GetFieldName(), int(t.GetNumber()), asc)
160		}
161	
162		limitN := req.GetLimit()
163		if limitN == 0 {
164			limitN = defaultLimit
165		}
166		plan = NewLimit(plan, req.GetOffset(), limitN)
167	
168		return plan, nil
169	}
170	
171	// buildTagProjection converts the proto tag projection into the model-level
172	// slice the BatchSchema builder consumes.
173	func buildTagProjection(req *measurev1.QueryRequest) []model.TagProjection {
174		tp := req.GetTagProjection()
175		if tp == nil {
176			return nil
177		}
178		families := tp.GetTagFamilies()
179		out := make([]model.TagProjection, 0, len(families))
180		for _, tf := range families {
181			out = append(out, model.TagProjection{
182				Family: tf.GetName(),
183				Names:  append([]string(nil), tf.GetTags()...),
184			})
185		}
186		return out
187	}
188	
189	// translateGroupBy builds the model GroupBy struct from the proto. A
190	// GroupBy must set tag_projection, time_bucket, or both (design §7.2 —
191	// bucketing alone, with no tag key, is a legal grouping). When
192	// tag_projection is present it must name exactly one family with non-empty
193	// tags (v1 single-family limitation), and every named tag must exist in the
194	// Measure schema. When time_bucket is present, its width is resolved per
195	// §5.3 and the request is checked against the bucketed streaming
196	// precondition (time-ascending input).
197	func translateGroupBy(req *measurev1.QueryRequest, measureSchema *databasev1.Measure) (*model.MeasureGroupBy, error) {
198		groupByProto := req.GetGroupBy()
199		families := groupByProto.GetTagProjection().GetTagFamilies()
200		tbProto := groupByProto.GetTimeBucket()
201		if len(families) == 0 && tbProto == nil {
202			return nil, fmt.Errorf("plan.Analyze: GroupBy must set tag_projection, time_bucket, or both")
203		}
204	
205		gb := &model.MeasureGroupBy{}
206		if len(families) > 0 {
207			if len(families) > 1 {
208				return nil, fmt.Errorf("plan.Analyze: GroupBy.tag_projection v1 supports a single tag family, got %d", len(families))
209			}
210			family := families[0]
211			if len(family.GetTags()) == 0 {
212				return nil, fmt.Errorf("plan.Analyze: GroupBy.tag_projection family %q has no tags", family.GetName())
213			}
214			gb.TagFamily = family.GetName()
215			gb.TagNames = append([]string(nil), family.GetTags()...)
216			if validateErr := validateGroupByTags(measureSchema, gb); validateErr != nil {
217				return nil, validateErr
218			}
219		}
220	
221		if tbProto != nil {
222			// A time-bucketed GroupBy without an Agg has no execution support:
223			// BatchTimeBucket's raw (no-AggSpec) shape reuses BatchAggregation's
224			// output layout, which — unlike BatchGroupByFirst's full schema
225			// passthrough — carries only tags and the bucket timestamp, silently
226			// dropping every projected field (and, on the distributed path, the
227			// series-id/version columns raw row merging requires). Reject rather
228			// than silently lose data; a bucketed raw GroupBy is a possible
229			// follow-up, not something this design ships.
230			if req.GetAgg() == nil {
231				return nil, fmt.Errorf("plan.Analyze: time_bucket requires Agg; a bucketed raw GroupBy (no aggregate) is not supported yet")
232			}
233			tb, tbErr := resolveTimeBucket(tbProto, measureSchema)
234			if tbErr != nil {
235				return nil, tbErr
236			}
237			if orderErr := validateBucketableOrdering(req); orderErr != nil {
238				return nil, orderErr
239			}
240			gb.TimeBucket = tb
241		}
242		return gb, nil
243	}
244	
245	// resolveTimeBucket implements the §5.3 width-resolution table: an explicit
246	// tb.Width wins; an empty Width falls back to the measure's own interval;
247	// both empty is rejected, and so is any width that fails to parse or is not
248	// strictly positive. There is deliberately no "must be a multiple of the
249	// interval" rule — Measure.interval is a declared write cadence, not an
250	// enforced storage invariant, so every positive width is equally meaningful.
251	func resolveTimeBucket(tb *measurev1.QueryRequest_GroupBy_TimeBucket, measureSchema *databasev1.Measure) (*model.MeasureTimeBucket, error) {
252		raw := tb.GetWidth()
253		if raw == "" {
254			raw = measureSchema.GetInterval()
255			if raw == "" {
256				return nil, fmt.Errorf("plan.Analyze: time_bucket needs a width: measure %q declares no interval", measureSchema.GetMetadata().GetName())
257			}
258		}
259		width, parseErr := timestamp.ParseDuration(raw)
260		if parseErr != nil {
261			return nil, fmt.Errorf("plan.Analyze: time_bucket width %q is not a valid duration: %w", raw, parseErr)
262		}
263		if width <= 0 {
264			return nil, fmt.Errorf("plan.Analyze: time_bucket width %q must be positive, got %s", raw, width)
265		}
266		return &model.MeasureTimeBucket{
267			Width:           raw,
268			WidthNanos:      int64(width),
269			UseIndexModeMap: measureSchema.GetIndexMode(),
270		}, nil
271	}
272	
273	// validateBucketableOrdering rejects a bucketed request whose order_by names
274	// a non-time index rule (design §7.2: both the streaming operator and the
275	// index-mode map fallback assume the request carries no ordering that would
276	// contradict time-ascending scan input). An aggregation request already
277	// carries no effective order_by today — Analyze never reads
278	// req.GetOrderBy(), and the distributed planner skips OrderBy resolution
279	// whenever Agg is set — so this is a belt-and-suspenders guard against a
280	// caller relying on a setting the engine would otherwise silently ignore,
281	// applied uniformly regardless of the streaming/map choice for a
282	// consistent contract.
283	func validateBucketableOrdering(req *measurev1.QueryRequest) error {
284		orderBy := req.GetOrderBy()
285		if ruleName := orderBy.GetIndexRuleName(); ruleName != "" {
286			return fmt.Errorf("plan.Analyze: time_bucket requires time ordering; order_by.index_rule_name %q is not supported on a bucketed query", ruleName)
287		}
288		// An empty index_rule_name with Sort == SORT_DESC still resolves to a
289		// time-ordered scan (index.OrderByTypeTime) per applyMeasureQueryOrdering
290		// — just descending instead of ascending. BatchTimeBucket's streaming
291		// path assumes ascending input specifically, not merely "time-ordered",
292		// so this must be rejected too.
293		if orderBy.GetSort() == modelv1.Sort_SORT_DESC {
294			return fmt.Errorf("plan.Analyze: time_bucket requires ascending time order; order_by.sort SORT_DESC is not supported on a bucketed query")
295		}
296		return nil
297	}
298	
299	// translateAgg builds the model Agg struct from the proto. Exactly one of
300	// field_name / tag_name must be set; a tag target additionally requires
301	// tag_family, which is what keeps the target resolvable when a schema carries
302	// the same tag name in two families. api/validate.UniqueTagNames rejects that
303	// shape, but only on the registry's create and update paths, so a schema
304	// registered before that check still loads and can reach here with a
305	// duplicate: the family qualifier is load-bearing, not decoration. The target
306	// is then checked against the §6 semantics matrix.
307	func translateAgg(req *measurev1.QueryRequest, measureSchema *databasev1.Measure) (*model.MeasureAgg, error) {
308		aggProto := req.GetAgg()
309		fieldName := aggProto.GetFieldName()
310		tagName := aggProto.GetTagName()
311		tagFamily := aggProto.GetTagFamily()
312	
313		switch {
314		case fieldName != "" && tagName != "":
315			return nil, fmt.Errorf("plan.Analyze: Agg must target exactly one of field_name or tag_name, got both (%q, %q)", fieldName, tagName)
316		case fieldName == "" && tagName == "":
317			return nil, fmt.Errorf("plan.Analyze: Agg must set exactly one of field_name or tag_name")
318		case tagName != "" && tagFamily == "":
319			return nil, fmt.Errorf("plan.Analyze: Agg.tag_name %q requires tag_family to be set", tagName)
320		case fieldName != "":
321			if validateErr := validateAggField(measureSchema, fieldName); validateErr != nil {
322				return nil, validateErr
323			}
324			return &model.MeasureAgg{FieldName: fieldName, Func: aggProto.GetFunction()}, nil
325		default:
326			if validateErr := validateAggTag(measureSchema, tagFamily, tagName, aggProto.GetFunction()); validateErr != nil {
327				return nil, validateErr
328			}
329			return &model.MeasureAgg{TagName: tagName, TagFamily: tagFamily, Func: aggProto.GetFunction()}, nil
330		}
331	}
332	
333	// ensureGroupByProjected returns a TagProjection slice guaranteed to
334	// include every GroupBy key tag. When the request already projects them
335	// the input slice is returned unchanged; otherwise the missing key tags
336	// are appended to (or create) the GroupBy family. Mirrors the row path,
337	// whose GroupBy resolves its key tag refs against the schema regardless
338	// of the request projection.
339	func ensureGroupByProjected(tp []model.TagProjection, gb *model.MeasureGroupBy) []model.TagProjection {
340		if gb == nil || gb.TagFamily == "" || len(gb.TagNames) == 0 {
341			return tp
342		}
343		out := append([]model.TagProjection(nil), tp...)
344		familyIdx := -1
345		for i := range out {
346			if out[i].Family == gb.TagFamily {
347				familyIdx = i
348				break
349			}
350		}
351		if familyIdx < 0 {
352			out = append(out, model.TagProjection{
353				Family: gb.TagFamily,
354				Names:  append([]string(nil), gb.TagNames...),
355			})
356			return out
357		}
358		present := make(map[string]struct{}, len(out[familyIdx].Names))
359		for _, n := range out[familyIdx].Names {
360			present[n] = struct{}{}
361		}
362		names := append([]string(nil), out[familyIdx].Names...)
363		for _, n := range gb.TagNames {
364			if _, ok := present[n]; !ok {
365				names = append(names, n)
366			}
367		}
368		out[familyIdx].Names = names
369		return out
370	}
371	
372	// ensureAggFieldProjected returns a FieldProjection slice guaranteed to
373	// include the Agg field. When already present the input is returned
374	// unchanged; otherwise the field is appended. Mirrors the row path,
375	// whose aggregation resolves its field ref against the schema regardless
376	// of the request projection.
377	func ensureAggFieldProjected(fp []string, agg *model.MeasureAgg) []string {
378		if agg == nil || agg.FieldName == "" {
379			return fp
380		}
381		for _, n := range fp {
382			if n == agg.FieldName {
383				return fp
384			}
385		}
386		out := append([]string(nil), fp...)
387		return append(out, agg.FieldName)
388	}
389	
390	// ensureAggTagProjected mirrors ensureGroupByProjected for an Agg tag
391	// target: when the caller's tag_projection already names it, agg.HideTag
392	// stays false and the caller gets both a tag and a field of that name in
393	// the output (design §5.2 — separate namespaces, nothing collides).
394	// Otherwise the tag is appended to its family (creating the family if
395	// absent) and agg.HideTag is set so the injected copy is not also emitted
396	// as a first-seen tag column alongside the aggregation result.
397	func ensureAggTagProjected(tp []model.TagProjection, agg *model.MeasureAgg) []model.TagProjection {
398		if agg == nil || agg.TagName == "" {
399			return tp
400		}
401		for _, fam := range tp {
402			if fam.Family != agg.TagFamily {
403				continue
404			}
405			for _, n := range fam.Names {
406				if n == agg.TagName {
407					return tp
408				}
409			}
410		}
411		agg.HideTag = true
412		out := append([]model.TagProjection(nil), tp...)
413		for i := range out {
414			if out[i].Family == agg.TagFamily {
415				out[i].Names = append(append([]string(nil), out[i].Names...), agg.TagName)
416				return out
417			}
418		}
419		return append(out, model.TagProjection{Family: agg.TagFamily, Names: []string{agg.TagName}})
420	}
421	
422	// validateGroupByTags ensures every name in gb.TagNames exists within the
423	// configured tag family of measureSchema.
424	func validateGroupByTags(measureSchema *databasev1.Measure, gb *model.MeasureGroupBy) error {
425		for _, tf := range measureSchema.GetTagFamilies() {
426			if tf.GetName() != gb.TagFamily {
427				continue
428			}
429			known := make(map[string]struct{}, len(tf.GetTags()))
430			for _, ts := range tf.GetTags() {
431				known[ts.GetName()] = struct{}{}
432			}
433			for _, name := range gb.TagNames {
434				if _, ok := known[name]; !ok {
435					return fmt.Errorf("plan.Analyze: GroupBy tag %s.%s not present in measure schema", gb.TagFamily, name)
436				}
437			}
438			return nil
439		}
440		return fmt.Errorf("plan.Analyze: GroupBy tag family %q not present in measure schema", gb.TagFamily)
441	}
442	
443	// validateAggField ensures the agg field name is a field defined on the
444	// Measure schema. Type compatibility (int/float) is enforced later by the
445	// BatchAggregation operator.
446	func validateAggField(measureSchema *databasev1.Measure, fieldName string) error {
447		for _, fs := range measureSchema.GetFields() {
448			if fs.GetName() == fieldName {
449				return nil
450			}
451		}
452		return fmt.Errorf("plan.Analyze: Agg field %q not present in measure schema", fieldName)
453	}
454	
455	// validateAggTag resolves (tagFamily, tagName) against measureSchema and
456	// enforces the §6 semantics matrix: array and TIMESTAMP tags are rejected
457	// outright (mirroring keyComponentSupported, the operator's own key-encoding
458	// limit, so the two cannot drift apart); SUM/MIN/MAX/MEAN additionally
459	// require TAG_TYPE_INT, while COUNT and COUNT_DISTINCT accept any tag type
460	// that survives the array/timestamp check.
461	func validateAggTag(measureSchema *databasev1.Measure, tagFamily, tagName string, fn modelv1.AggregationFunction) error {
462		spec := findTagSpec(measureSchema, tagFamily, tagName)
463		if spec == nil {
464			return fmt.Errorf("plan.Analyze: Agg tag %s.%s not present in measure schema", tagFamily, tagName)
465		}
466		colType, typeErr := tagTypeToColumnTypeMG(spec.GetType())
467		if typeErr != nil {
468			return fmt.Errorf("plan.Analyze: Agg tag %s.%s has type %s, which cannot be an aggregation target", tagFamily, tagName, spec.GetType())
469		}
470		if !measure.KeyComponentSupported(colType) {
471			return fmt.Errorf("plan.Analyze: Agg tag %s.%s has type %s, which cannot be an aggregation target", tagFamily, tagName, spec.GetType())
472		}
473		switch fn {
474		case modelv1.AggregationFunction_AGGREGATION_FUNCTION_COUNT,
475			modelv1.AggregationFunction_AGGREGATION_FUNCTION_COUNT_DISTINCT:
476			return nil
477		case modelv1.AggregationFunction_AGGREGATION_FUNCTION_SUM,
478			modelv1.AggregationFunction_AGGREGATION_FUNCTION_MIN,
479			modelv1.AggregationFunction_AGGREGATION_FUNCTION_MAX,
480			modelv1.AggregationFunction_AGGREGATION_FUNCTION_MEAN:
481			if colType != vectorized.ColumnTypeInt64 {
482				return fmt.Errorf("plan.Analyze: Agg tag %s.%s: %s is not supported over tag type %s", tagFamily, tagName, fn, spec.GetType())
483			}
484			return nil
485		default:
486			return fmt.Errorf("plan.Analyze: Agg.Function is UNSPECIFIED or unknown")
487		}
488	}
489	
490	// validateCountDistinctPushdown enforces design §7.4's decomposability
491	// condition for a COUNT_DISTINCT Agg: every one of the measure's routing
492	// tags (its sharding_key if configured, else its entity — the same
493	// fallback banyand/liaison/grpc/discovery.go's navigateByLocator already
494	// uses) must be covered by the GroupBy keys or be the aggregation target
495	// itself. If a routing tag is uncovered, a value sharing that routing tag
496	// value can land on more than one shard, so per-shard distinct counts are
497	// not disjoint and summing them would double-count.
498	//
499	// Evaluated identically for standalone and distributed requests — the
500	// design's own principle: a query either works everywhere or nowhere. A
501	// standalone deployment has no sharding and could serve any COUNT_DISTINCT
502	// correctly today, but must not silently diverge from what the same query
503	// does once the measure is sharded.
504	//
505	// Routing tag names are resolved against the schema by bare name — not
506	// family — because Entity/ShardingKey.TagNames carry no family qualifier
507	// at the schema level; pkg/partition/entity.go's NewEntityLocator /
508	// NewShardingKeyLocator already resolve them the same way via
509	// pbv1.FindTagByName. This function resolves each routing tag's actual
510	// family from the schema before comparing, so it does not introduce a new
511	// bare-name ambiguity on the GroupBy/target side, which IS family-qualified.
512	func validateCountDistinctPushdown(req *measurev1.QueryRequest, measureSchema *databasev1.Measure) error {
513		agg := req.GetAgg()
514		if agg == nil || agg.GetFunction() != modelv1.AggregationFunction_AGGREGATION_FUNCTION_COUNT_DISTINCT {
515			return nil
516		}
517		routingTagNames := measureSchema.GetShardingKey().GetTagNames()
518		if len(routingTagNames) == 0 {
519			routingTagNames = measureSchema.GetEntity().GetTagNames()
520		}
521		families := measureSchema.GetTagFamilies()
522		groupByFamily, groupByTagNames := distributedGroupByTagKey(req.GetGroupBy())
523		targetFamily, targetName := agg.GetTagFamily(), agg.GetTagName()
524		for _, routingName := range routingTagNames {
